class Solution {
public:
    int maxScore(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end(), std::greater<int>());
        long long running = 0;
        int ans = 0;
        for (int x : nums) {
            running += x;
            if (running > 0) {
                ans++;
            } else {
                break;
            }
        }
        return ans;
    }
};

class Solution {
    public int maxScore(int[] nums) {
        java.util.Arrays.sort(nums);
        long running = 0;
        int ans = 0;
        for (int i = nums.length - 1; i >= 0; i--) {
            running += nums[i];
            if (running > 0) {
                ans++;
            } else {
                break;
            }
        }
        return ans;
    }
}

var maxScore = function(nums) {
    nums.sort((a, b) => b - a);
    let running = 0;
    let ans = 0;
    for (const x of nums) {
        running += x;
        if (running > 0) {
            ans++;
        } else {
            break;
        }
    }
    return ans;
};
